/**
 * Pitcher frontend — calls Go backend via Wails v3 bindings.
 *
 * Build steps (from project root):
 *   1. go install github.com/wailsapp/wails/v3/cmd/wails3@latest
 *   2. wails3 generate bindings
 *   3. cd frontend && npm install && npm run build
 *
 * The generated binding path below is the default produced by
 * "wails3 generate bindings" for package main in this module.
 * Adjust if the generator puts the files in a different location.
 */

// Generated by `wails3 generate bindings` — do not edit the bindings directory.
import { PitcherService } from '../bindings/github.com/intermernet/pitcher'

// ── DOM references ──────────────────────────────────────────────────────────
const $infoBar      = document.getElementById('info-bar')
const $inputDevice  = document.getElementById('input-device')
const $outputDevice = document.getElementById('output-device')
const $algorithm    = document.getElementById('algorithm')
const $frameSize    = document.getElementById('frame-size')
const $oversampling = document.getElementById('oversampling')
const $latency      = document.getElementById('latency-display')
const $pitchSlider  = document.getElementById('pitch-slider')
const $pitchValue   = document.getElementById('pitch-value')
const $volSlider    = document.getElementById('volume-slider')
const $volValue     = document.getElementById('volume-value')

// ── Helpers ─────────────────────────────────────────────────────────────────
function populateSelect(sel, items, selectedIndex) {
  sel.innerHTML = ''
  items.forEach((item, i) => {
    const opt = document.createElement('option')
    opt.value = String(i)
    opt.textContent = typeof item === 'string' ? item : item.name
    opt.selected = i === selectedIndex
    sel.appendChild(opt)
  })
}

function updateLatency(ms) {
  $latency.textContent = `Latency: ${ms.toFixed(1)} ms`
}

// ── Boot ─────────────────────────────────────────────────────────────────────
async function init() {
  const [state, algoNames, frameSizes, oversamplingOpts, inputDevs, outputDevs] =
    await Promise.all([
      PitcherService.GetState(),
      PitcherService.GetAlgoNames(),
      PitcherService.GetFrameSizes(),
      PitcherService.GetOversamplingOptions(),
      PitcherService.GetInputDevices(),
      PitcherService.GetOutputDevices(),
    ])

  // Info bar
  const exclStr = state.exclusive ? 'Yes' : 'No'
  $infoBar.textContent =
    `Channels: ${state.channels}  |  Sample Rate: ${state.sampleRate} Hz  |  ` +
    `Periods: ${state.periods}  |  Buffer: ${state.bufferSize} frames  |  Exclusive: ${exclStr}`

  // Devices
  populateSelect($inputDevice,  inputDevs,  state.inputIdx)
  populateSelect($outputDevice, outputDevs, state.outputIdx)

  // Algorithm
  populateSelect($algorithm, algoNames, algoNames.indexOf(state.algoName))

  // Frame size & oversampling
  populateSelect($frameSize,    frameSizes,      frameSizes.indexOf(String(state.frameSize)))
  populateSelect($oversampling, oversamplingOpts, oversamplingOpts.indexOf(String(state.oversampling)))

  // Latency
  updateLatency(state.latencyMs)

  // Pitch slider
  $pitchSlider.value = String(state.shift)
  $pitchValue.textContent = `${state.shift >= 0 ? '+' : ''}${state.shift.toFixed(2)} st`

  // Volume slider
  $volSlider.value = String(state.volume)
  $volValue.textContent = state.volume.toFixed(2)

  attachListeners()
}

// ── Listeners ────────────────────────────────────────────────────────────────
function attachListeners() {

  $inputDevice.addEventListener('change', () => {
    PitcherService.SetInputDevice(parseInt($inputDevice.value, 10))
  })

  $outputDevice.addEventListener('change', () => {
    PitcherService.SetOutputDevice(parseInt($outputDevice.value, 10))
  })

  $algorithm.addEventListener('change', () => {
    PitcherService.SetAlgorithm($algorithm.options[$algorithm.selectedIndex].textContent)
  })

  $frameSize.addEventListener('change', async () => {
    const ms = await PitcherService.SetFrameSize($frameSize.value)
    updateLatency(ms)
  })

  $oversampling.addEventListener('change', async () => {
    const ms = await PitcherService.SetOversampling($oversampling.value)
    updateLatency(ms)
  })

  $pitchSlider.addEventListener('input', () => {
    const v = parseFloat($pitchSlider.value)
    $pitchValue.textContent = `${v >= 0 ? '+' : ''}${v.toFixed(2)} st`
    PitcherService.SetPitch(v)
  })

  $volSlider.addEventListener('input', () => {
    const v = parseFloat($volSlider.value)
    $volValue.textContent = v.toFixed(2)
    PitcherService.SetVolume(v)
  })
}

init().catch(err => {
  console.error('Pitcher init failed:', err)
  document.getElementById('info-bar').textContent = 'Error initialising — check the console'
})
